using MediatR;using OAS.Application.Abstractions.Messaging;using OAS.Application.Common.Exceptions;using OAS.Application.Sales.Abstractions;using OAS.Application.Sales.Authorization;using OAS.Contracts.Sales.Production;
namespace OAS.Application.Sales.Production.Queries;
public sealed record GetOpticalProductionJobQuery(Guid Id):IQuery<OpticalProductionJobDto>,IAuthorizedRequest{public IReadOnlyCollection<string> RequiredPermissions{get;}=[SalesPermissions.View];}
public sealed record GetOpticalProductionJobsQuery(OpticalProductionStatus? Status,Guid? SalesInvoiceId):IQuery<IReadOnlyList<OpticalProductionJobDto>>,IAuthorizedRequest{public IReadOnlyCollection<string> RequiredPermissions{get;}=[SalesPermissions.View];}
public sealed class GetOpticalProductionJobQueryHandler(IOpticalProductionQueryService q):IRequestHandler<GetOpticalProductionJobQuery,OpticalProductionJobDto>{public async Task<OpticalProductionJobDto> Handle(GetOpticalProductionJobQuery r,CancellationToken ct)=>await q.GetAsync(r.Id,ct)??throw new NotFoundException("OpticalProductionJob",r.Id);}
